import{_ as n,C as i,o,c as a,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"有检查点，不等于可以继续执行","description":"","frontmatter":{"title":"有检查点，不等于可以继续执行","date":"2026-08-25","column":"industry-architecture","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"When a resumable agent cannot know whether a durable Session append committed before an interruption, what state must be resolved before the runtime is allowed to continue model execution?","summary":"OpenAI Agents Python 的一项已合并变更把不确定 Session Append 变成持久 Recovery State。Resume Authority 必须等待权威 History Reconciliation；该模式避免一个 Session 边界上的 Blind Replay，但不会产生分布式 Exactly-once Semantics。","sources":["research/analysis/Q-20260825-02-uncertain-persistence-gates-resume.md"],"item_id":"Q-20260825-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-25-checkpoint-not-permission-to-resume-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/industry/2026-08-25-checkpoint-not-permission-to-resume.md","filePath":"zh/industry/2026-08-25-checkpoint-not-permission-to-resume.md","lastUpdated":1787666502000}'),c={name:"zh/industry/2026-08-25-checkpoint-not-permission-to-resume.md"};function l(p,e,d,u,m,h){const t=i("ArticleCover");return o(),a("div",null,[r(t,{image:"/assets/covers/daily-2026-08-25-checkpoint-not-permission-to-resume-cover-v2.png",kicker:"行业架构 · 每日研究",title:"有检查点，不等于可以继续执行",summary:"OpenAI Agents Python 的一项已合并变更把不确定 Session Append 变成持久 Recovery State。Resume Authority 必须等待权威 History Reconciliation；该模式避免一个 Session 边界上的 Blind Replay，但不会产生分布式 Exactly-once Semantics。",version:"Q-20260825-02",status:"Daily Runtime V5 · 2026-08-25",languageHref:"/en/industry/2026-08-25-checkpoint-not-permission-to-resume",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="有检查点-不等于可以继续执行" tabindex="-1">有检查点，不等于可以继续执行 <a class="header-anchor" href="#有检查点-不等于可以继续执行" aria-label="Permalink to &quot;有检查点，不等于可以继续执行&quot;">​</a></h1><p>一次 Session Append 返回错误。Backend 可能拒绝了它，也可能已经写入 Item、只是 Ack 丢失。Retry 假设未提交，可能造成重复；Skip 假设已提交，可能造成丢失。两种选择都把缺少证据变成了猜测。</p><p>OpenAI Agents Python 在 2026-08-25 合并的一项变更，为这种不确定性建立了持久身份。它把 Pending Session Write 写入 <code>RunState</code>，Resume 时重读权威 Session History，并在允许下一次 Model Call 前分类观察结果：Already Committed 不重放，Unchanged 可以补写，其他状态属于 Ambiguous 并 Fail Closed。</p><p>架构结论比“谨慎重试”更强，但比 Exactly-once Execution 更窄：<strong>Checkpoint 可以恢复 Process State，却不能自动恢复 Continuation Authority。</strong> 未来 Reasoning 所依赖的 Durable Boundary 未解决前，Runtime 不应获得继续执行的权力。</p><h2 id="resumability-保存状态-不保存确定性" tabindex="-1">Resumability 保存状态，不保存确定性 <a class="header-anchor" href="#resumability-保存状态-不保存确定性" aria-label="Permalink to &quot;Resumability 保存状态，不保存确定性&quot;">​</a></h2><p>Checkpoint 回答进程能否重建，却不会自动回答最后一个 Durable Effect 是否完成。Transport Exception 是 Epistemic Event：调用方知道 Ack 失败，但不知道 Storage 最终包含什么。</p><p>如果这种不确定性在进程停止时丢失，恢复后的 Runtime 就没有原则化选择，只能重复 Append 或从不完整 History 继续。所选变更保存了未决 Intent 本身：Session Identity、Item Batch、已知的 Pre-write History Fingerprint 与 Persisted-item Count。</p><p>于是，不确定性成为 State Machine 的一部分。只有 <code>Running</code>、<code>Paused</code> 与 <code>Resumed</code> 不够，Runtime 还需要“Unresolved Durable Effect”状态，用它暂停更高层工作。</p><h2 id="reconciliation-是新-reasoning-之前的门禁" tabindex="-1">Reconciliation 是新 Reasoning 之前的门禁 <a class="header-anchor" href="#reconciliation-是新-reasoning-之前的门禁" aria-label="Permalink to &quot;Reconciliation 是新 Reasoning 之前的门禁&quot;">​</a></h2><p>Streaming 与 Non-streaming Resume Path 都在下一次 Model Call 前处理 Pending Write。这个顺序不可交换：新 Reasoning 不应消费最后边界仍有争议的 History。</p><p>算法重读权威 Session History，并比较稳定 Item Fingerprint。如果观察到的 Tail 等于记录的 Pre-write History 加 Pending Item，Append 已提交，不需要重放；如果 History 仍等于写入前状态，Append 仍缺失，可以执行；两者都不匹配时，状态就是 Ambiguous。</p><p>Ambiguity 时 Fail Closed 可能拒绝合法 Concurrent Extension，这确实牺牲 Availability。但在没有 Revision Token、CAS 或受治理 Merge Rule 时，自动接受会虚构 Runtime 并不拥有的知识。显式 Error 保留冲突，等待 Repair，而不是静默改写 History。</p><p>这套三路分类正是 Reconciliation 与通用 Retry 的区别：它先要求权威 Storage 说明哪个已表达世界真实存在，再允许 Execution 推进。</p><h2 id="recovery-evidence-与-execution-progress-是不同记录" tabindex="-1">Recovery Evidence 与 Execution Progress 是不同记录 <a class="header-anchor" href="#recovery-evidence-与-execution-progress-是不同记录" aria-label="Permalink to &quot;Recovery Evidence 与 Execution Progress 是不同记录&quot;">​</a></h2><p>健壮控制面至少应分别保存三类事实：预期 Durable Effect、用于分类的 Storage Evidence，以及更高层 Execution Position。只保存第三类的 Checkpoint 会诱导不安全继续。</p><p>Recovery Record 还应严格绑定 Identity。如果恢复后的 Runtime 可能指向不同 Backend Implementation 或 Namespace，仅有 Logical Session ID 可能不够。Backend Identity、Serialization Version 与 Fingerprint Scheme 决定“相等”到底意味着什么。</p><p>Operator 需要一条 Decision Trail：观察到 Pending Intent、重读权威 History、得到分类、授予或拒绝 Continuation Authority。它能解释 Model Call 为何恢复或停止，而不需要暴露完整 Conversation Payload。</p><p>如果多个恢复 Worker 可能并发，还需要另一层 Ownership。所选实现只有 In-process Guard，没有分布式 CAS；独立副本能够同时处理同一 Session 时，系统需要 Lease、Revision Token 或 CAS-backed Append。</p><h2 id="session-reconciliation-不会让-external-effect-具有事务性" tabindex="-1">Session Reconciliation 不会让 External Effect 具有事务性 <a class="header-anchor" href="#session-reconciliation-不会让-external-effect-具有事务性" aria-label="Permalink to &quot;Session Reconciliation 不会让 External Effect 具有事务性&quot;">​</a></h2><p>精确 Session Fingerprint 只证明被比较 Serialization Representation 相等，不能证明 Session Item 所代表的 Tool Call、Payment、Message 或 Deployment 恰好提交一次。External-effect Identity 与 Receipt 需要自己的 Reconciliation Boundary。</p><p>该实现也没有建立分布式 Exactly-once Session Persistence。它证明的是一个有界规则：对一个 Pending Append 与一个权威 History，保存 Intent、重读、分类，并在新 Model Execution 前对歧义停止。</p><p>剩余设计问题由此自然出现：Session Backend 是否应暴露 Revision 或 CAS？如何区分合法 Concurrent Extension 与 Corruption？Pending-write State 应绑定哪一种 Backend Identity？Recovered Item 在授权继续之前需要什么 External-effect Evidence？</p><p><strong>一手证据：</strong> <a href="https://github.com/openai/openai-agents-python/commit/40f0d9fccbe03bf704e4ef044c7c81b807e594da" target="_blank" rel="noreferrer">OpenAI Agents Python 已合并提交 40f0d9fc</a>。公开实现支持有界 Session-write Reconciliation，不支持分布式 Exactly-once Execution 或 Transactional External Effect。</p>',23))])}const R=n(c,[["render",l]]);export{g as __pageData,R as default};
